from rules import resolve


def solve(data):
    return resolve(data)

def resolve(data):
    packages = data.get("packages", {})
    roots = data.get("roots", {})
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = data.get("features", [])
    names = sorted(packages)

    def active_deps(row):
        return [
            dep for dep in row.get("deps", [])
            if not dep.get("feature") or dep.get("feature") in features
        ]

    def options(name, constraints):
        result = []
        for row in packages.get(name, []):
            version = row["version"]
            if version in blocked.get(name, []):
                continue
            if name in pins and version != pins[name]:
                continue
            if all(lo <= version <= hi for lo, hi in constraints):
                result.append(row)
        return sorted(result, key=lambda row: row["version"], reverse=True)

    def has_cycle(graph):
        visiting = set()
        visited = set()

        def visit(node):
            if node in visiting:
                return True
            if node in visited:
                return False
            visiting.add(node)
            for target in graph.get(node, ()):
                if visit(target):
                    return True
            visiting.remove(node)
            visited.add(node)
            return False

        return any(visit(node) for node in graph)

    constraints = {name: [tuple(interval)] for name, interval in roots.items()}
    best_vector = None
    best_versions = None
    unrestricted = {}
    for name in names:
        unrestricted[name] = options(name, [])

    def search(constraints, chosen, selected_rows, graph):
        nonlocal best_vector, best_versions

        for name, version in chosen.items():
            if name in constraints and not all(lo <= version <= hi for lo, hi in constraints[name]):
                return

        unresolved = sorted(name for name in constraints if name not in chosen)
        available = {}
        for name in unresolved:
            available[name] = options(name, constraints[name])
            if not available[name]:
                return

        if best_vector is not None:
            upper = []
            for name in names:
                if name in chosen:
                    upper.append(chosen[name])
                elif name in constraints:
                    upper.append(available[name][0]["version"])
                else:
                    versions = unrestricted.get(name, [])
                    upper.append(max(-1, versions[0]["version"]) if versions else -1)
            if tuple(upper) <= best_vector:
                return

        if not unresolved:
            if has_cycle(graph):
                return
            vector = tuple(chosen.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = dict(chosen)
            return

        name = unresolved[0]
        for row in available[name]:
            version = row["version"]
            next_chosen = dict(chosen)
            next_chosen[name] = version
            next_rows = dict(selected_rows)
            next_rows[name] = row
            next_constraints = {key: list(value) for key, value in constraints.items()}
            next_graph = {key: list(value) for key, value in graph.items()}
            deps = active_deps(row)
            next_graph[name] = [dep["name"] for dep in deps]
            for dep in deps:
                next_constraints.setdefault(dep["name"], []).append((dep["min"], dep["max"]))
            if not has_cycle(next_graph):
                search(next_constraints, next_chosen, next_rows, next_graph)

    search(constraints, {}, {}, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}
